values (
  'es-trivia-geografia-mundial',
  'Trivia de geografía mundial: capitales, océanos y extremos',
  'Ocho preguntas de geografía sobre capitales, océanos, desiertos y los extremos del planeta. Sin trampas: solo el mapa.',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'geography'),
  '[{"id":"q1","question":"¿Cuál es la capital de Australia?","options":[{"id":"a","text":"Sídney","is_correct":false},{"id":"b","text":"Melbourne","is_correct":false},{"id":"c","text":"Canberra","is_correct":true},{"id":"d","text":"Perth","is_correct":false}],"explanation":"Canberra se construyó como capital en 1913, entre Sídney y Melbourne."},{"id":"q2","question":"¿Cuál es el océano más grande del planeta?","options":[{"id":"a","text":"Océano Atlántico","is_correct":false},{"id":"b","text":"Océano Índico","is_correct":false},{"id":"c","text":"Océano Pacífico","is_correct":true},{"id":"d","text":"Océano Ártico","is_correct":false}],"explanation":"El Pacífico cubre aproximadamente un tercio de la superficie del planeta."},{"id":"q3","question":"¿Cuál es el país más grande por superficie terrestre?","options":[{"id":"a","text":"Canadá","is_correct":false},{"id":"b","text":"China","is_correct":false},{"id":"c","text":"Rusia","is_correct":true},{"id":"d","text":"Estados Unidos","is_correct":false}],"explanation":"Rusia ocupa once husos horarios y dos continentes."},{"id":"q4","question":"¿En qué continente está Egipto?","options":[{"id":"a","text":"Asia","is_correct":false},{"id":"b","text":"África","is_correct":true},{"id":"c","text":"Europa","is_correct":false},{"id":"d","text":"Oceanía","is_correct":false}],"explanation":"La península del Sinaí llega a Asia, pero el país es africano."},{"id":"q5","question":"¿Cuál es la capital de Canadá?","options":[{"id":"a","text":"Toronto","is_correct":false},{"id":"b","text":"Vancouver","is_correct":false},{"id":"c","text":"Montreal","is_correct":false},{"id":"d","text":"Ottawa","is_correct":true}],"explanation":"Ottawa está en Ontario, en la frontera con Quebec."},{"id":"q6","question":"¿Cuál es el desierto cálido más grande del mundo?","options":[{"id":"a","text":"Desierto de Gobi","is_correct":false},{"id":"b","text":"Desierto del Sahara","is_correct":true},{"id":"c","text":"Desierto de Atacama","is_correct":false},{"id":"d","text":"Desierto de Sonora","is_correct":false}],"explanation":"El Sahara tiene una extensión parecida a la de Estados Unidos."},{"id":"q7","question":"¿Cuál es la montaña más alta sobre el nivel del mar?","options":[{"id":"a","text":"K2","is_correct":false},{"id":"b","text":"Kilimanjaro","is_correct":false},{"id":"c","text":"Everest","is_correct":true},{"id":"d","text":"Denali","is_correct":false}],"explanation":"El Everest alcanza 8.849 metros sobre el nivel del mar, entre Nepal y China."},{"id":"q8","question":"¿Qué país tiene forma de bota?","options":[{"id":"a","text":"España","is_correct":false},{"id":"b","text":"Grecia","is_correct":false},{"id":"c","text":"Italia","is_correct":true},{"id":"d","text":"Portugal","is_correct":false}],"explanation":"La península italiana y el tacón de Apulia dibujan la silueta de una bota."}]'::jsonb,
  null,
  array['geografía', 'trivia', 'capitales', 'mundo']::text[],
