  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"How many players from one team are on the pitch in football (soccer)?","options":[{"id":"a","text":"9","is_correct":false},{"id":"b","text":"10","is_correct":false},{"id":"c","text":"11","is_correct":true},{"id":"d","text":"12","is_correct":false}],"explanation":"Eleven per side, including the goalkeeper."},{"id":"q2","question":"How often are the Summer Olympic Games normally held?","options":[{"id":"a","text":"Every two years","is_correct":false},{"id":"b","text":"Every three years","is_correct":false},{"id":"c","text":"Every four years","is_correct":true},{"id":"d","text":"Every five years","is_correct":false}],"explanation":"The four-year cycle is called an Olympiad."},{"id":"q3","question":"How many points is a basket scored from beyond the arc worth in basketball?","options":[{"id":"a","text":"1","is_correct":false},{"id":"b","text":"2","is_correct":false},{"id":"c","text":"3","is_correct":true},{"id":"d","text":"4","is_correct":false}],"explanation":"Two points inside the arc, three beyond it, one from the free-throw line."},{"id":"q4","question":"Which country won the 2022 FIFA World Cup?","options":[{"id":"a","text":"France","is_correct":false},{"id":"b","text":"Brazil","is_correct":false},{"id":"c","text":"Argentina","is_correct":true},{"id":"d","text":"Germany","is_correct":false}],"explanation":"Argentina beat France on penalties after a 3-3 final in Qatar."},{"id":"q5","question":"In which sport is the Tour de France contested?","options":[{"id":"a","text":"Running","is_correct":false},{"id":"b","text":"Cycling","is_correct":true},{"id":"c","text":"Motor racing","is_correct":false},{"id":"d","text":"Rowing","is_correct":false}],"explanation":"It is a three-week road cycling race held mostly in France."},{"id":"q6","question":"How many players from one team are on the court in volleyball?","options":[{"id":"a","text":"5","is_correct":false},{"id":"b","text":"6","is_correct":true},{"id":"c","text":"7","is_correct":false},{"id":"d","text":"8","is_correct":false}],"explanation":"Six per side on an indoor court, with rotations after each serve change."},{"id":"q7","question":"How many players from one team are on the court in basketball?","options":[{"id":"a","text":"4","is_correct":false},{"id":"b","text":"5","is_correct":true},{"id":"c","text":"6","is_correct":false},{"id":"d","text":"7","is_correct":false}],"explanation":"Five per team, on a court with a basket at each end."},{"id":"q8","question":"In tennis, what is a score of zero called?","options":[{"id":"a","text":"Nil","is_correct":false},{"id":"b","text":"Love","is_correct":true},{"id":"c","text":"Duck","is_correct":false},{"id":"d","text":"Blank","is_correct":false}],"explanation":"Love comes from the French ''l''oeuf'', an egg, drawn as a zero."}]'::jsonb,
  null,
  array['sports', 'trivia', 'football', 'basketball', 'tennis']::text[],
  3,
