   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-historia-mundiales-futbol',
  'Trivia de los Mundiales: sedes, finales y campeones',
  'Del Maracanazo de 1950 a Rusia 2018: ocho preguntas sobre las sedes, las finales y los campeones de la Copa Mundial de la FIFA.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"¿Qué selección ganó el Mundial de 1950 tras vencer a Brasil en el Maracaná?","options":[{"id":"a","text":"Uruguay","is_correct":true},{"id":"b","text":"Suecia","is_correct":false},{"id":"c","text":"España","is_correct":false},{"id":"d","text":"Italia","is_correct":false}],"explanation":"Uruguay venció 2-1 a Brasil el 16 de julio de 1950 en el partido decisivo, conocido como el Maracanazo."},{"id":"q2","question":"¿Qué país organizó el Mundial de 1962?","options":[{"id":"a","text":"Argentina","is_correct":false},{"id":"b","text":"Uruguay","is_correct":false},{"id":"c","text":"México","is_correct":false},{"id":"d","text":"Chile","is_correct":true}],"explanation":"Chile fue sede en 1962: Brasil se quedó con el título y el anfitrión terminó tercero."},{"id":"q3","question":"¿Qué país fue el primero en organizar dos Mundiales?","options":[{"id":"a","text":"Italia","is_correct":false},{"id":"b","text":"México","is_correct":true},{"id":"c","text":"Francia","is_correct":false},{"id":"d","text":"Brasil","is_correct":false}],"explanation":"México fue sede en 1970 y en 1986, y así se convirtió en el primer país en organizar dos Copas del Mundo."},{"id":"q4","question":"¿Quién anotó el gol conocido como «la mano de Dios» en México 1986?","options":[{"id":"a","text":"Pelé","is_correct":false},{"id":"b","text":"Mario Kempes","is_correct":false},{"id":"c","text":"Diego Maradona","is_correct":true},{"id":"d","text":"Gary Lineker","is_correct":false}],"explanation":"Maradona marcó con la mano ante Inglaterra en los cuartos de final del 22 de junio de 1986."},{"id":"q5","question":"¿Qué selección ganó el Mundial de 1978, jugado en Argentina?","options":[{"id":"a","text":"Argentina","is_correct":true},{"id":"b","text":"Países Bajos","is_correct":false},{"id":"c","text":"Brasil","is_correct":false},{"id":"d","text":"Italia","is_correct":false}],"explanation":"Argentina venció 3-1 a los Países Bajos en la prórroga de la final, jugada en el estadio Monumental."},{"id":"q6","question":"¿Qué selección ganó el Mundial de Alemania 2006?","options":[{"id":"a","text":"Francia","is_correct":false},{"id":"b","text":"Alemania","is_correct":false},{"id":"c","text":"Portugal","is_correct":false},{"id":"d","text":"Italia","is_correct":true}],"explanation":"Italia empató 1-1 con Francia en la final de Berlín y ganó la copa en la tanda de penales."},{"id":"q7","question":"¿En qué país se jugó el Mundial de 2018?","options":[{"id":"a","text":"Alemania","is_correct":false},{"id":"b","text":"Rusia","is_correct":true},{"id":"c","text":"Brasil","is_correct":false},{"id":"d","text":"Catar","is_correct":false}],"explanation":"Rusia organizó el Mundial de 2018, que ganó Francia al vencer 4-2 a Croacia en la final."},{"id":"q8","question":"¿Qué selección ganó el Mundial de Estados Unidos 1994?","options":[{"id":"a","text":"Italia","is_correct":false},{"id":"b","text":"Alemania","is_correct":false},{"id":"c","text":"Brasil","is_correct":true},{"id":"d","text":"Suecia","is_correct":false}],"explanation":"Brasil venció a Italia en los penales tras un 0-0, la primera final de un Mundial definida desde el punto penal."}]'::jsonb,
  null,
  array['fútbol', 'mundiales', 'historia del deporte', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
