   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-comida-callejera',
  'Trivia de comida callejera: tacos, falafel y churros',
  'Del trompo del taco al pastor al takoyaki de Osaka: ocho preguntas sobre la comida callejera mas famosa del mundo.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"El trompo vertical de los tacos al pastor llego a Mexico con inmigrantes de que pais?","options":[{"id":"a","text":"Espana","is_correct":false},{"id":"b","text":"Libano","is_correct":true},{"id":"c","text":"Italia","is_correct":false},{"id":"d","text":"Grecia","is_correct":false}],"explanation":"Los inmigrantes libaneses llevaron el asador de shawarma a Mexico en el siglo XX y alli nacio el trompo del pastor."},{"id":"q2","question":"El shawarma, carne asada en un espeton vertical, es comida callejera tipica de que region?","options":[{"id":"a","text":"Europa del Este","is_correct":false},{"id":"b","text":"Oriente Medio","is_correct":true},{"id":"c","text":"Sudeste Asiatico","is_correct":false},{"id":"d","text":"America Central","is_correct":false}],"explanation":"El shawarma tiene origen otomano y hoy se vende en puestos de todo el Levante y Turquia."},{"id":"q3","question":"Los takoyaki, las bolitas fritas de Osaka, van rellenas de que ingrediente?","options":[{"id":"a","text":"Camaron","is_correct":false},{"id":"b","text":"Pollo","is_correct":false},{"id":"c","text":"Pulpo","is_correct":true},{"id":"d","text":"Cangrejo","is_correct":false}],"explanation":"Tako significa pulpo en japones; el plato nacio en Osaka en 1935."},{"id":"q4","question":"El elote y los esquites, maiz preparado con chile, limon y queso, son un clasico callejero de que pais?","options":[{"id":"a","text":"Espana","is_correct":false},{"id":"b","text":"Mexico","is_correct":true},{"id":"c","text":"Chile","is_correct":false},{"id":"d","text":"Marruecos","is_correct":false}],"explanation":"El elote en vaso o en mazorca es uno de los antojitos callejeros mas populares de Mexico."},{"id":"q5","question":"El pho, la sopa de fideos de arroz vendida en puestos callejeros, es el plato insignia de que pais?","options":[{"id":"a","text":"Vietnam","is_correct":true},{"id":"b","text":"Tailandia","is_correct":false},{"id":"c","text":"China","is_correct":false},{"id":"d","text":"Japon","is_correct":false}],"explanation":"El pho nacio en el norte de Vietnam a comienzos del siglo XX."},{"id":"q6","question":"Las arepas son comida callejera emblematica de Venezuela y de que otro pais?","options":[{"id":"a","text":"Ecuador","is_correct":false},{"id":"b","text":"Colombia","is_correct":true},{"id":"c","text":"Bolivia","is_correct":false},{"id":"d","text":"Uruguay","is_correct":false}],"explanation":"La arepa de maiz es alimento basico tanto de Venezuela como de Colombia desde antes de la colonia."},{"id":"q7","question":"Que bocado callejero aleman consiste en salchicha con ketchup y curry en polvo?","options":[{"id":"a","text":"Bratwurst","is_correct":false},{"id":"b","text":"Currywurst","is_correct":true},{"id":"c","text":"Schnitzel","is_correct":false},{"id":"d","text":"Kebab","is_correct":false}],"explanation":"El currywurst se invento en Berlin en 1949, en el puesto de Herta Heuwer."},{"id":"q8","question":"El falafel egipcio, llamado ta''ameya, se prepara tradicionalmente con que legumbre?","options":[{"id":"a","text":"Garbanzos","is_correct":false},{"id":"b","text":"Habas","is_correct":true},{"id":"c","text":"Lentejas","is_correct":false},{"id":"d","text":"Guisantes","is_correct":false}],"explanation":"A diferencia del falafel de garbanzos del resto de la region, el egipcio usa habas."}]'::jsonb,
  null,
  array['comida', 'comida-callejera', 'trivia', 'gastronomia']::text[],
  4,
  'published',
  false,
  false,
  now()
)
