values (
  'es-trivia-especies-amenazadas',
  'Trivia de especies amenazadas: animales al borde',
  'De la vaquita del golfo de California al kakapo de Nueva Zelanda: ocho preguntas sobre los animales mas raros del planeta.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"La mayoria de los pandas gigantes salvajes vive en los bosques de bambu de que provincia china?","options":[{"id":"a","text":"Yunnan","is_correct":false},{"id":"b","text":"Sichuan","is_correct":true},{"id":"c","text":"Guangdong","is_correct":false},{"id":"d","text":"Heilongjiang","is_correct":false}],"explanation":"Las montanas de Sichuan concentran la mayor parte del habitat silvestre del panda."},{"id":"q2","question":"La vaquita, el mamifero marino mas raro del mundo, vive unicamente en que lugar?","options":[{"id":"a","text":"El mar Caribe","is_correct":false},{"id":"b","text":"El golfo de California","is_correct":true},{"id":"c","text":"El mar de Bering","is_correct":false},{"id":"d","text":"La bahia de Bengala","is_correct":false}],"explanation":"Se estima que quedan menos de una decena de vaquitas en el norte del golfo de California."},{"id":"q3","question":"El kakapo, un loro nocturno incapaz de volar, es originario de que pais?","options":[{"id":"a","text":"Australia","is_correct":false},{"id":"b","text":"Nueva Zelanda","is_correct":true},{"id":"c","text":"Madagascar","is_correct":false},{"id":"d","text":"Papua Nueva Guinea","is_correct":false}],"explanation":"Sobreviven menos de 250 kakapos, todos en islas libres de depredadores de Nueva Zelanda."},{"id":"q4","question":"El leopardo de Amur habita los bosques de la frontera entre Rusia y que otro pais?","options":[{"id":"a","text":"Mongolia","is_correct":false},{"id":"b","text":"China","is_correct":true},{"id":"c","text":"Kazajistan","is_correct":false},{"id":"d","text":"Corea del Sur","is_correct":false}],"explanation":"La mayor parte de los leopardos de Amur que quedan vive en el Lejano Oriente ruso y el noreste de China."},{"id":"q5","question":"Cual es la especie de rinoceronte mas grande que existe hoy?","options":[{"id":"a","text":"Rinoceronte negro","is_correct":false},{"id":"b","text":"Rinoceronte blanco","is_correct":true},{"id":"c","text":"Rinoceronte indio","is_correct":false},{"id":"d","text":"Rinoceronte de Java","is_correct":false}],"explanation":"El rinoceronte blanco puede superar los 2.000 kg; la subespecie del sur se recupero de menos de 100 ejemplares."},{"id":"q6","question":"Todos los rinocerontes de Java salvajes que quedan viven dentro de que parque nacional?","options":[{"id":"a","text":"Komodo","is_correct":false},{"id":"b","text":"Ujung Kulon","is_correct":true},{"id":"c","text":"Chitwan","is_correct":false},{"id":"d","text":"Kruger","is_correct":false}],"explanation":"Ujung Kulon, en el extremo oeste de Java, alberga la unica poblacion conocida, de unos 70 animales."},{"id":"q7","question":"El gorila de montana sobrevive sobre todo en los bosques de que region?","options":[{"id":"a","text":"Los volcanes Virunga, en Africa central","is_correct":true},{"id":"b","text":"Las selvas de Borneo","is_correct":false},{"id":"c","text":"Los Andes colombianos","is_correct":false},{"id":"d","text":"Las montanas de Madagascar","is_correct":false}],"explanation":"Habita la region de los volcanes Virunga, compartida por Ruanda, Uganda y la RD del Congo."},{"id":"q8","question":"Que mide la Lista Roja de la UICN?","options":[{"id":"a","text":"El crecimiento de las poblaciones","is_correct":false},{"id":"b","text":"El riesgo de extincion de las especies","is_correct":true},{"id":"c","text":"La calidad del habitat","is_correct":false},{"id":"d","text":"El volumen del trafico ilegal","is_correct":false}],"explanation":"La Lista Roja clasifica a las especies de Preocupacion Menor a Extinta segun su riesgo de extincion."}]'::jsonb,
  null,
  array['animales', 'conservacion', 'naturaleza', 'trivia']::text[],
  4,
  'published',
  false,
  false,
  now()
)
