insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-movie-directors-trivia',
  'Movie Directors Trivia: The Names Behind the Camera',
  'Eight questions on the directors who shaped cinema, from Hitchcock''s suspense to Miyazaki''s animated worlds.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"Who directed ''Jaws'' (1975) and ''E.T. the Extra-Terrestrial'' (1982)?","options":[{"id":"a","text":"George Lucas","is_correct":false},{"id":"b","text":"Steven Spielberg","is_correct":true},{"id":"c","text":"Robert Zemeckis","is_correct":false},{"id":"d","text":"Ridley Scott","is_correct":false}],"explanation":"Spielberg''s two blockbusters helped define the modern summer movie."},{"id":"q2","question":"Who wrote and directed ''Pulp Fiction'' (1994)?","options":[{"id":"a","text":"Martin Scorsese","is_correct":false},{"id":"b","text":"David Fincher","is_correct":false},{"id":"c","text":"Quentin Tarantino","is_correct":true},{"id":"d","text":"Joel Coen","is_correct":false}],"explanation":"Tarantino won the Palme d''Or and an Oscar for the film''s screenplay."},{"id":"q3","question":"Which director made ''Psycho'' (1960) and ''Vertigo'' (1958)?","options":[{"id":"a","text":"Alfred Hitchcock","is_correct":true},{"id":"b","text":"Orson Welles","is_correct":false},{"id":"c","text":"Billy Wilder","is_correct":false},{"id":"d","text":"Fritz Lang","is_correct":false}],"explanation":"Hitchcock, the ''Master of Suspense'', never won a competitive Oscar despite five nominations."},{"id":"q4","question":"Who directed ''Titanic'' (1997) and ''Avatar'' (2009)?","options":[{"id":"a","text":"James Cameron","is_correct":true},{"id":"b","text":"Peter Jackson","is_correct":false},{"id":"c","text":"Steven Spielberg","is_correct":false},{"id":"d","text":"Michael Bay","is_correct":false}],"explanation":"Both films became the highest-grossing movie of their time."},{"id":"q5","question":"Which New Zealand director made ''The Lord of the Rings'' trilogy?","options":[{"id":"a","text":"Guillermo del Toro","is_correct":false},{"id":"b","text":"Peter Jackson","is_correct":true},{"id":"c","text":"Sam Raimi","is_correct":false},{"id":"d","text":"Taika Waititi","is_correct":false}],"explanation":"Jackson shot all three films back to back in his native New Zealand."},{"id":"q6","question":"Who directed the animated film ''Spirited Away'' (2001)?","options":[{"id":"a","text":"Isao Takahata","is_correct":false},{"id":"b","text":"Mamoru Hosoda","is_correct":false},{"id":"c","text":"Satoshi Kon","is_correct":false},{"id":"d","text":"Hayao Miyazaki","is_correct":true}],"explanation":"Miyazaki''s film won the Oscar for Best Animated Feature, Studio Ghibli''s biggest international hit."},{"id":"q7","question":"Who was the first woman to win the Oscar for Best Director?","options":[{"id":"a","text":"Sofia Coppola","is_correct":false},{"id":"b","text":"Kathryn Bigelow","is_correct":true},{"id":"c","text":"Jane Campion","is_correct":false},{"id":"d","text":"Greta Gerwig","is_correct":false}],"explanation":"Bigelow won in 2010 for ''The Hurt Locker''."},{"id":"q8","question":"Which director made ''The Dark Knight'' trilogy and ''Inception'' (2010)?","options":[{"id":"a","text":"Denis Villeneuve","is_correct":false},{"id":"b","text":"Zack Snyder","is_correct":false},{"id":"c","text":"Christopher Nolan","is_correct":true},{"id":"d","text":"J.J. Abrams","is_correct":false}],"explanation":"Nolan is known for practical effects and non-linear storytelling."}]'::jsonb,
  null,
  array['movies', 'directors', 'cinema', 'trivia']::text[],
  3,
  'published',
