  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"The first message sent over ARPANET in 1969 was meant to be ''LOGIN''. What was actually transmitted before the system crashed?","options":[{"id":"a","text":"LO","is_correct":true},{"id":"b","text":"LOG","is_correct":false},{"id":"c","text":"LOGIN","is_correct":false},{"id":"d","text":"HELLO","is_correct":false}],"explanation":"The system crashed after two letters, so ''LO'' was the first message ever sent."},{"id":"q2","question":"At which organization did Tim Berners-Lee invent the World Wide Web?","options":[{"id":"a","text":"MIT","is_correct":false},{"id":"b","text":"NASA","is_correct":false},{"id":"c","text":"CERN","is_correct":true},{"id":"d","text":"IBM","is_correct":false}],"explanation":"Berners-Lee proposed the Web in 1989 at CERN, the physics laboratory in Geneva."},{"id":"q3","question":"What was the first widely used graphical web browser, released in 1993?","options":[{"id":"a","text":"Netscape Navigator","is_correct":false},{"id":"b","text":"Mosaic","is_correct":true},{"id":"c","text":"Internet Explorer","is_correct":false},{"id":"d","text":"Lynx","is_correct":false}],"explanation":"NCSA Mosaic made the Web visual; its team went on to build Netscape Navigator."},{"id":"q4","question":"Which company did Larry Page and Sergey Brin found in 1998?","options":[{"id":"a","text":"Yahoo","is_correct":false},{"id":"b","text":"AltaVista","is_correct":false},{"id":"c","text":"Google","is_correct":true},{"id":"d","text":"Amazon","is_correct":false}],"explanation":"Google began as a Stanford research project called ''BackRub''."},{"id":"q5","question":"Which company started in 1994 as an online bookstore?","options":[{"id":"a","text":"eBay","is_correct":false},{"id":"b","text":"Amazon","is_correct":true},{"id":"c","text":"Barnes & Noble","is_correct":false},{"id":"d","text":"Alibaba","is_correct":false}],"explanation":"Jeff Bezos founded Amazon in July 1994 and shipped the first book a year later."},{"id":"q6","question":"Which free online encyclopedia, written by volunteers, launched in 2001?","options":[{"id":"a","text":"Britannica Online","is_correct":false},{"id":"b","text":"Encarta","is_correct":false},{"id":"c","text":"About.com","is_correct":false},{"id":"d","text":"Wikipedia","is_correct":true}],"explanation":"Wikipedia launched in January 2001 and overtook Encarta within a few years."},{"id":"q7","question":"In what year was YouTube founded?","options":[{"id":"a","text":"2003","is_correct":false},{"id":"b","text":"2005","is_correct":true},{"id":"c","text":"2007","is_correct":false},{"id":"d","text":"2001","is_correct":false}],"explanation":"Three former PayPal employees founded it; the first video went up in April 2005."},{"id":"q8","question":"In what year did Apple release the first iPhone?","options":[{"id":"a","text":"2005","is_correct":false},{"id":"b","text":"2007","is_correct":true},{"id":"c","text":"2006","is_correct":false},{"id":"d","text":"2009","is_correct":false}],"explanation":"Steve Jobs presented it in January 2007 as ''an iPod, a phone and an internet communicator''."}]'::jsonb,
  null,
  array['internet', 'technology', 'history', 'trivia']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
