   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-historia-de-internet',
  'Trivia de la Historia de Internet: de ARPANET al iPhone',
  'Ocho preguntas sobre los hitos que construyeron el mundo en línea, del primer mensaje de 1969 al primer iPhone.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"El primer mensaje enviado por ARPANET en 1969 debía ser ''LOGIN''. ¿Qué se transmitió antes de que el sistema cayera?","options":[{"id":"a","text":"LOG","is_correct":false},{"id":"b","text":"LO","is_correct":true},{"id":"c","text":"LOGIN","is_correct":false},{"id":"d","text":"HOLA","is_correct":false}],"explanation":"El sistema cayó tras dos letras, así que ''LO'' fue el primer mensaje de la historia."},{"id":"q2","question":"¿En qué organización inventó Tim Berners-Lee la World Wide Web?","options":[{"id":"a","text":"el MIT","is_correct":false},{"id":"b","text":"la NASA","is_correct":false},{"id":"c","text":"el CERN","is_correct":true},{"id":"d","text":"IBM","is_correct":false}],"explanation":"Berners-Lee propuso la Web en 1989 en el CERN, el laboratorio de física de Ginebra."},{"id":"q3","question":"¿Cuál fue el primer navegador gráfico de uso masivo, lanzado en 1993?","options":[{"id":"a","text":"Netscape Navigator","is_correct":false},{"id":"b","text":"Internet Explorer","is_correct":false},{"id":"c","text":"Mosaic","is_correct":true},{"id":"d","text":"Lynx","is_correct":false}],"explanation":"NCSA Mosaic hizo visual la Web; su equipo construyó después Netscape Navigator."},{"id":"q4","question":"¿Qué empresa fundaron Larry Page y Sergey Brin en 1998?","options":[{"id":"a","text":"Yahoo","is_correct":false},{"id":"b","text":"Google","is_correct":true},{"id":"c","text":"AltaVista","is_correct":false},{"id":"d","text":"Amazon","is_correct":false}],"explanation":"Google nació como un proyecto de investigación en Stanford llamado ''BackRub''."},{"id":"q5","question":"¿Qué empresa empezó en 1994 como una librería en línea?","options":[{"id":"a","text":"eBay","is_correct":false},{"id":"b","text":"Barnes & Noble","is_correct":false},{"id":"c","text":"Alibaba","is_correct":false},{"id":"d","text":"Amazon","is_correct":true}],"explanation":"Jeff Bezos fundó Amazon en julio de 1994 y envió el primer libro un año después."},{"id":"q6","question":"¿Qué enciclopedia en línea gratuita, escrita por voluntarios, se lanzó en 2001?","options":[{"id":"a","text":"Encarta","is_correct":false},{"id":"b","text":"Wikipedia","is_correct":true},{"id":"c","text":"Britannica Online","is_correct":false},{"id":"d","text":"About.com","is_correct":false}],"explanation":"Wikipedia se lanzó en enero de 2001 y superó a Encarta en pocos años."},{"id":"q7","question":"¿En qué año se fundó YouTube?","options":[{"id":"a","text":"2003","is_correct":false},{"id":"b","text":"2001","is_correct":false},{"id":"c","text":"2005","is_correct":true},{"id":"d","text":"2007","is_correct":false}],"explanation":"Lo fundaron tres exempleados de PayPal; el primer video se subió en abril de 2005."},{"id":"q8","question":"¿En qué año lanzó Apple el primer iPhone?","options":[{"id":"a","text":"2005","is_correct":false},{"id":"b","text":"2006","is_correct":false},{"id":"c","text":"2009","is_correct":false},{"id":"d","text":"2007","is_correct":true}],"explanation":"Steve Jobs lo presentó en enero de 2007 como ''un iPod, un teléfono y un comunicador de internet''."}]'::jsonb,
  null,
  array['internet', 'tecnología', 'historia', 'trivia']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-nobel-prizes-trivia',
  'Nobel Prizes Trivia: A Century of Genius',
  'Eight questions on the world''s most famous award: its founder, its records and its most surprising winners.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"The Nobel Prizes were established by the will of which inventor?","options":[{"id":"a","text":"Thomas Edison","is_correct":false},{"id":"b","text":"Alfred Nobel","is_correct":true},{"id":"c","text":"Alexander Graham Bell","is_correct":false},{"id":"d","text":"Guglielmo Marconi","is_correct":false}],"explanation":"Nobel, the inventor of dynamite, left most of his fortune to fund the prizes."},{"id":"q2","question":"In what year were the first Nobel Prizes awarded?","options":[{"id":"a","text":"1895","is_correct":false},{"id":"b","text":"1910","is_correct":false},{"id":"c","text":"1901","is_correct":true},{"id":"d","text":"1921","is_correct":false}],"explanation":"The first ceremony was held in 1901, the fifth anniversary of Nobel''s death."},{"id":"q3","question":"Who is the only person to win Nobel Prizes in two different sciences?","options":[{"id":"a","text":"Linus Pauling","is_correct":false},{"id":"b","text":"Albert Einstein","is_correct":false},{"id":"c","text":"Niels Bohr","is_correct":false},{"id":"d","text":"Marie Curie","is_correct":true}],"explanation":"Curie won Physics in 1903 and Chemistry in 1911."},{"id":"q4","question":"The Nobel Peace Prize is awarded in which city?","options":[{"id":"a","text":"Stockholm","is_correct":false},{"id":"b","text":"Oslo","is_correct":true},{"id":"c","text":"Geneva","is_correct":false},{"id":"d","text":"Copenhagen","is_correct":false}],"explanation":"All prizes are presented in Stockholm except the Peace Prize, awarded in Oslo."},{"id":"q5","question":"Albert Einstein won the 1921 Nobel Prize in Physics mainly for explaining what?","options":[{"id":"a","text":"The theory of relativity","is_correct":false},{"id":"b","text":"Nuclear fission","is_correct":false},{"id":"c","text":"The photoelectric effect","is_correct":true},{"id":"d","text":"Brownian motion","is_correct":false}],"explanation":"Relativity was still controversial, so the committee cited the photoelectric effect."},{"id":"q6","question":"Which Nobel Prize was added later and is not one of the original five?","options":[{"id":"a","text":"Economic Sciences","is_correct":true},{"id":"b","text":"Peace","is_correct":false},{"id":"c","text":"Literature","is_correct":false},{"id":"d","text":"Mathematics","is_correct":false}],"explanation":"The economics prize, funded by Sweden''s central bank, was first awarded in 1969."},{"id":"q7","question":"Which singer-songwriter won the Nobel Prize in Literature in 2016?","options":[{"id":"a","text":"Leonard Cohen","is_correct":false},{"id":"b","text":"Bob Dylan","is_correct":true},{"id":"c","text":"Paul McCartney","is_correct":false},{"id":"d","text":"Bruce Springsteen","is_correct":false}],"explanation":"Dylan was the first songwriter to win the literature prize, ''for new poetic expressions''."},{"id":"q8","question":"Which of these fields has no Nobel Prize?","options":[{"id":"a","text":"Physics","is_correct":false},{"id":"b","text":"Medicine","is_correct":false},{"id":"c","text":"Mathematics","is_correct":true},{"id":"d","text":"Chemistry","is_correct":false}],"explanation":"Mathematics was never among Nobel''s categories; the Fields Medal is its closest equivalent."}]'::jsonb,
  null,
  array['nobel', 'science', 'awards', 'trivia']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-premios-nobel',
  'Trivia de los Premios Nobel: un Siglo de Genios',
  'Ocho preguntas sobre el premio más famoso del mundo: su fundador, sus récords y sus ganadores más sorprendentes.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Qué inventor estableció los Premios Nobel en su testamento?","options":[{"id":"a","text":"Thomas Edison","is_correct":false},{"id":"b","text":"Alfred Nobel","is_correct":true},{"id":"c","text":"Alexander Graham Bell","is_correct":false},{"id":"d","text":"Guglielmo Marconi","is_correct":false}],"explanation":"Nobel, el inventor de la dinamita, dejó casi toda su fortuna para financiar los premios."},{"id":"q2","question":"¿En qué año se entregaron los primeros Premios Nobel?","options":[{"id":"a","text":"1895","is_correct":false},{"id":"b","text":"1901","is_correct":true},{"id":"c","text":"1910","is_correct":false},{"id":"d","text":"1921","is_correct":false}],"explanation":"La primera ceremonia fue en 1901, al cumplirse cinco años de la muerte de Nobel."},{"id":"q3","question":"¿Quién es la única persona con dos Premios Nobel en ciencias distintas?","options":[{"id":"a","text":"Linus Pauling","is_correct":false},{"id":"b","text":"Albert Einstein","is_correct":false},{"id":"c","text":"Marie Curie","is_correct":true},{"id":"d","text":"Niels Bohr","is_correct":false}],"explanation":"Curie ganó el de Física en 1903 y el de Química en 1911."},{"id":"q4","question":"¿En qué ciudad se entrega el Nobel de la Paz?","options":[{"id":"a","text":"Estocolmo","is_correct":false},{"id":"b","text":"Ginebra","is_correct":false},{"id":"c","text":"Oslo","is_correct":true},{"id":"d","text":"Copenhague","is_correct":false}],"explanation":"Todos los premios se entregan en Estocolmo salvo el de la Paz, que se entrega en Oslo."},{"id":"q5","question":"Einstein ganó el Nobel de Física de 1921 principalmente por explicar qué fenómeno?","options":[{"id":"a","text":"La teoría de la relatividad","is_correct":false},{"id":"b","text":"El efecto fotoeléctrico","is_correct":true},{"id":"c","text":"La fisión nuclear","is_correct":false},{"id":"d","text":"El movimiento browniano","is_correct":false}],"explanation":"La relatividad aún era controvertida, así que el comité citó el efecto fotoeléctrico."},{"id":"q6","question":"¿Qué autor de ''Cien años de soledad'' ganó el Nobel de Literatura en 1982?","options":[{"id":"a","text":"Pablo Neruda","is_correct":false},{"id":"b","text":"Octavio Paz","is_correct":false},{"id":"c","text":"Gabriel García Márquez","is_correct":true},{"id":"d","text":"Mario Vargas Llosa","is_correct":false}],"explanation":"García Márquez lo ganó en 1982; Vargas Llosa lo haría en 2010."},{"id":"q7","question":"¿Qué poeta chileno ganó el Nobel de Literatura en 1971?","options":[{"id":"a","text":"Pablo Neruda","is_correct":true},{"id":"b","text":"Gabriela Mistral","is_correct":false},{"id":"c","text":"Vicente Huidobro","is_correct":false},{"id":"d","text":"Jorge Luis Borges","is_correct":false}],"explanation":"Neruda ganó en 1971; Mistral, también chilena, lo había ganado en 1945."},{"id":"q8","question":"¿Cuál de estos campos NO tiene Premio Nobel?","options":[{"id":"a","text":"Física","is_correct":false},{"id":"b","text":"Medicina","is_correct":false},{"id":"c","text":"Química","is_correct":false},{"id":"d","text":"Matemáticas","is_correct":true}],"explanation":"Las matemáticas nunca estuvieron entre las categorías; la Medalla Fields es su equivalente más cercano."}]'::jsonb,
  null,
  array['nobel', 'ciencia', 'premios', 'trivia']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-famous-landmarks-trivia',
  'Famous Landmarks Trivia: Icons of the World',
  'Eight questions on the monuments everyone recognizes, from the Eiffel Tower to the rose-red city of Petra.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'geography'),
  '[{"id":"q1","question":"The Eiffel Tower was built for which 1889 event?","options":[{"id":"a","text":"The coronation of Napoleon III","is_correct":false},{"id":"b","text":"The Exposition Universelle","is_correct":true},{"id":"c","text":"The opening of the Paris Metro","is_correct":false},{"id":"d","text":"The end of the Franco-Prussian War","is_correct":false}],"explanation":"It marked 100 years since the French Revolution and was meant to stand for only 20 years."},{"id":"q2","question":"The Colosseum stands in the centre of which city?","options":[{"id":"a","text":"Athens","is_correct":false},{"id":"b","text":"Naples","is_correct":false},{"id":"c","text":"Rome","is_correct":true},{"id":"d","text":"Istanbul","is_correct":false}],"explanation":"The nearly 2,000-year-old amphitheatre could hold around 50,000 spectators."},{"id":"q3","question":"The Taj Mahal was built by which Mughal emperor?","options":[{"id":"a","text":"Akbar","is_correct":false},{"id":"b","text":"Shah Jahan","is_correct":true},{"id":"c","text":"Aurangzeb","is_correct":false},{"id":"d","text":"Babur","is_correct":false}],"explanation":"Shah Jahan built it in Agra as a mausoleum for his wife Mumtaz Mahal."},{"id":"q4","question":"Machu Picchu was brought to international attention in 1911 by which explorer?","options":[{"id":"a","text":"Charles Darwin","is_correct":false},{"id":"b","text":"Thor Heyerdahl","is_correct":false},{"id":"c","text":"Hiram Bingham","is_correct":true},{"id":"d","text":"Francisco Pizarro","is_correct":false}],"explanation":"Bingham, an American historian, publicized the Inca citadel after his 1911 expedition."},{"id":"q5","question":"The statue of Christ the Redeemer overlooks which city?","options":[{"id":"a","text":"Sao Paulo","is_correct":false},{"id":"b","text":"Rio de Janeiro","is_correct":true},{"id":"c","text":"Buenos Aires","is_correct":false},{"id":"d","text":"Lisbon","is_correct":false}],"explanation":"Completed in 1931, it stands atop Corcovado mountain in Rio de Janeiro."},{"id":"q6","question":"The Statue of Liberty was a gift to the United States from which country?","options":[{"id":"a","text":"England","is_correct":false},{"id":"b","text":"Spain","is_correct":false},{"id":"c","text":"Italy","is_correct":false},{"id":"d","text":"France","is_correct":true}],"explanation":"Designed by Frederic Auguste Bartholdi, it was dedicated in New York Harbour in 1886."},{"id":"q7","question":"''Big Ben'' is the nickname of the Great Bell inside which London tower?","options":[{"id":"a","text":"The Tower of London","is_correct":false},{"id":"b","text":"Nelson''s Column","is_correct":false},{"id":"c","text":"The Elizabeth Tower","is_correct":true},{"id":"d","text":"Westminster Cathedral","is_correct":false}],"explanation":"The tower was renamed the Elizabeth Tower in 2012 for the Queen''s Diamond Jubilee."},{"id":"q8","question":"Which ancient city in Jordan is famous for buildings carved into rose-red rock?","options":[{"id":"a","text":"Palmyra","is_correct":false},{"id":"b","text":"Petra","is_correct":true},{"id":"c","text":"Luxor","is_correct":false},{"id":"d","text":"Persepolis","is_correct":false}],"explanation":"Petra''s most famous facade, Al-Khazneh (''the Treasury''), was carved by the Nabataeans."}]'::jsonb,
  null,
  array['landmarks', 'monuments', 'travel', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-monumentos-famosos',
  'Trivia de Monumentos Famosos: Iconos del Mundo',
  'Ocho preguntas sobre los monumentos que todo el mundo reconoce, de la Torre Eiffel a la ciudad rosada de Petra.',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'geography'),
  '[{"id":"q1","question":"¿Para qué evento de 1889 se construyó la Torre Eiffel?","options":[{"id":"a","text":"La coronación de Napoleón III","is_correct":false},{"id":"b","text":"La apertura del metro de París","is_correct":false},{"id":"c","text":"La Exposición Universal","is_correct":true},{"id":"d","text":"El fin de la guerra franco-prusiana","is_correct":false}],"explanation":"Marcaba el centenario de la Revolución Francesa y debía durar solo 20 años."},{"id":"q2","question":"El Coliseo se encuentra en el centro de qué ciudad?","options":[{"id":"a","text":"Atenas","is_correct":false},{"id":"b","text":"Roma","is_correct":true},{"id":"c","text":"Nápoles","is_correct":false},{"id":"d","text":"Estambul","is_correct":false}],"explanation":"El anfiteatro, de casi 2.000 años, podía albergar a unos 50.000 espectadores."},{"id":"q3","question":"¿Qué emperador mogol ordenó construir el Taj Mahal?","options":[{"id":"a","text":"Akbar","is_correct":false},{"id":"b","text":"Aurangzeb","is_correct":false},{"id":"c","text":"Shah Jahan","is_correct":true},{"id":"d","text":"Babur","is_correct":false}],"explanation":"Shah Jahan lo construyó en Agra como mausoleo para su esposa Mumtaz Mahal."},{"id":"q4","question":"¿Qué explorador dio a conocer Machu Picchu al mundo en 1911?","options":[{"id":"a","text":"Charles Darwin","is_correct":false},{"id":"b","text":"Hiram Bingham","is_correct":true},{"id":"c","text":"Thor Heyerdahl","is_correct":false},{"id":"d","text":"Francisco Pizarro","is_correct":false}],"explanation":"Bingham, un historiador estadounidense, dio a conocer la ciudadela inca tras su expedición de 1911."},{"id":"q5","question":"El Cristo Redentor se alza sobre qué ciudad?","options":[{"id":"a","text":"São Paulo","is_correct":false},{"id":"b","text":"Buenos Aires","is_correct":false},{"id":"c","text":"Lisboa","is_correct":false},{"id":"d","text":"Río de Janeiro","is_correct":true}],"explanation":"Inaugurado en 1931, se encuentra en la cima del cerro del Corcovado."},{"id":"q6","question":"La Estatua de la Libertad fue un regalo a Estados Unidos de qué país?","options":[{"id":"a","text":"Inglaterra","is_correct":false},{"id":"b","text":"Francia","is_correct":true},{"id":"c","text":"España","is_correct":false},{"id":"d","text":"Italia","is_correct":false}],"explanation":"Diseñada por Frédéric Auguste Bartholdi, se inauguró en el puerto de Nueva York en 1886."},{"id":"q7","question":"¿En qué ciudad está la Sagrada Familia, la obra inacabada de Gaudí?","options":[{"id":"a","text":"Madrid","is_correct":false},{"id":"b","text":"Sevilla","is_correct":false},{"id":"c","text":"Barcelona","is_correct":true},{"id":"d","text":"Valencia","is_correct":false}],"explanation":"Lleva en construcción desde 1882 y es el monumento más visitado de España."},{"id":"q8","question":"¿Qué ciudad antigua de Jordania es famosa por sus edificios tallados en la roca?","options":[{"id":"a","text":"Palmira","is_correct":false},{"id":"b","text":"Luxor","is_correct":false},{"id":"c","text":"Persépolis","is_correct":false},{"id":"d","text":"Petra","is_correct":true}],"explanation":"La fachada más famosa de Petra, Al-Khazneh (''el Tesoro''), fue tallada por los nabateos."}]'::jsonb,
  null,
  array['monumentos', 'viajes', 'geografía', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
